function UIBossDetailDialog:InitData()
    local parameters = self.controller.Argument.parameters
    local levelId = parameters.levelId --- 关卡id

    if levelId == Constants.SpecialQuestId.Mirror then
        ---@type FairylandComponent
        local FairylandComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.FairylandComponent)
        local FairylandUtils = import("Game.Fairyland.FairylandUtils")
         self.allQuestLineup, self.allWaveMonsterData = FairylandComponent.dojo:GetQuestMirrorAllWaveEnemyData(FairylandUtils.CurrentEnterQuestId)
        self.isMultiStage = false
    else
        ---@type table<number, WaveVo>
        local allQuestLineup = questConfMgr:GetAllQuestLineupVo(levelId)
        self.allQuestLineup =  allQuestLineup

        -- 获取关卡是否是多阶段boss关卡
        local questVo = questConfMgr:GetQuestVoById(levelId)
        self.isMultiStage = isNotNull(questVo.isMultiStage) and questVo.isMultiStage == 1
    end

    
end

---InitOneWaveMonsterVos
---初始化一轮的MonsterTypeVos
function UIBossDetailDialog:InitOneWaveMonsterVos()
    local index = self.tabIndex
    local oneWaveMonsterData = self.allWaveMonsterData[index]
    if oneWaveMonsterData then return oneWaveMonsterData end

    oneWaveMonsterData = {}
    ---@type WaveVo
    local waveVo     = self.allQuestLineup[index]
    local wave1NpcId = waveVo.wave1NpcId
    local wave1NpcType = waveVo.wave1NpcType
    local attrs      = waveVo.attribute
    local skinIds    = waveVo.skinId

    for i, monsterId in ipairs(wave1NpcId) do
        --- 克隆一份数据 直接覆盖需要修改的字段
        ---@type MonsterTypeVo
        local monsterTypeVo = clone(cardConfMgr:GetMonsterTypeVoById(monsterId))
        monsterTypeVo.monsterClass = checkNumber(wave1NpcType[i])
        if checkNumber(attrs[i]) > 0 then
            monsterTypeVo.attribute = checkNumber(attrs[i])
        elseif monsterTypeVo.role > 0 then
            local cardVo = cardConfMgr:GetCardBySkinRefId(monsterTypeVo.skinId)
            monsterTypeVo.attribute = cardVo.attributeType
        end
        if checkNumber(skinIds[i]) > 0 then
            monsterTypeVo.skinId = checkNumber(skinIds[i])
        end
        table.insert(oneWaveMonsterData, monsterTypeVo)
    end

    self.allWaveMonsterData[index] = oneWaveMonsterData
    return oneWaveMonsterData
end

---InitMonsterSkillData
---初始化怪物技能数据
---@param monsterTypeVo MonsterTypeVo
function UIBossDetailDialog:InitMonsterSkillData(monsterTypeVo)
    if monsterTypeVo.skillData ~= nil then
        self.monsterSkillData = monsterTypeVo.skillData
        return monsterTypeVo.skillData
    end
    local monsterSkillData = CardUtils.InitMonsterSkillData(monsterTypeVo)
    self.monsterSkillData = monsterSkillData
    return monsterSkillData
end

function UIBossDetailDialog:InitUI()
    UIEventProxy.Create(self.CloseButton.gameObject).onPointerClick = Bind(self, self.OnClickCloseButtonAction)
    UIEventProxy.Create(self.WeaknessButton.gameObject).onPointerClick = Bind(self, self.OnClickWeaknessButtonAction)

    GameUtils.UpdateUIShowState(self.TabNodeScrollRoot.gameObject, false)
    if self.isMultiStage then
        self:RefreshMultiStageBtnGroup()
    else
        self:RefreshTabNodeScrollView()
    end
    self:RefreshBG()
end

