function UIBossDetailDialog:RefreshUI()
    --- 初始化一轮的怪物vo 数据
    local oneWaveMonsterData = self:InitOneWaveMonsterVos()
    self:RefreshHeadNodeScrollView(oneWaveMonsterData)
    local monsterTypeVo = oneWaveMonsterData[self.monsterIndex]
    self:RefreshMonsterInfo(monsterTypeVo)
end

function UIBossDetailDialog:RefreshTabNodeScrollView()
    local scrollView = self.TabNodeScrollView
    local count = table.count(self.allQuestLineup)
    local isShow = count >= 1
    GameUtils.UpdateUIShowState(self.TabNodeScrollRoot.gameObject, isShow)
    if not isShow then return end
    if not scrollView.IsListViewInit then
        scrollView:InitListView(count, Bind(self, self.OnGetTabItemByIndex))
    else
        GameUtils.ReloadData(scrollView, count)
    end
    scrollView.ScrollRect.horizontal = count > 4
end

function UIBossDetailDialog:OnGetTabItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local position = index + 1
    -- 创建cell
    local cell = listView:NewListViewItem(PrefabNameTabNode)

    if not KTool.IsNull(cell) then
        -- cell绑定的脚本
        local cellViewMB = GetLuaBehaviour(cell.gameObject, PrefabPathTabNode)
        if not KTool.IsNull(cellViewMB) then
            ---@type UIBossDetailTabNodeMB
            local mbEnv = cellViewMB.Env
            if not cell.IsInitHandlerCalled then
                cell.IsInitHandlerCalled = true
                mbEnv = cellViewMB.Env
                mbEnv:SetCallback(Bind(self, self.OnClickTabNodeAction))
            end

            ---@type WaveVo
            local waveVo = self.allQuestLineup[position]
            mbEnv:RefreshUI(position, waveVo)
            mbEnv:RefreshSelectState(self.tabIndex == position)
        end
    end

    return cell
end

function UIBossDetailDialog:RefreshMultiStageBtnGroup()
    if not self.isMultiStage then
        return
    end

    KTool.SetActive(self.RT_MultiStageBtnGroup, true)

    local btnList = {}

    local count = table.count(self.allQuestLineup)
    for i = 1, count, 1 do
        local btnGo = KTool.Instantiate(self.RT_MultiStageBtnParent.gameObject, self.RT_MultiStageBtnNode.gameObject)
        local btnIcon = btnGo.transform:Find("ImgIcon")
        local btnFX = btnGo.transform:Find("UIFX_LoopGlow")
        local btnSImg = btnIcon:GetComponent(typeof(UISwitchImage))
        table.insert(btnList, {fx = btnFX, simg = btnSImg})
        SetButtonAction(btnIcon.gameObject, function()
            self.tabIndex = i
            self.monsterIndex = 1
            self:RefreshUI()
            -- 切换按钮状态
            for j = 1, count, 1 do
                if j == i then
                    KTool.SetActive(btnList[j].fx, true)
                    btnList[j].simg.Status = 2
                else
                    KTool.SetActive(btnList[j].fx, false)
                    btnList[j].simg.Status = 1
                end
            end
        end)
        -- 默认选中第一个按钮
        if i == 1 then
            KTool.SetActive(btnFX, true)
            btnSImg.Status = 2
        end
    end

    KTool.SetActive(self.RT_MultiStageBtnNode, false)
end

---RefreshTabNodeSelectState
---@param index number
---@param isSelect boolean
function UIBossDetailDialog:RefreshTabNodeSelectState(index, isSelect)
    local TabNodeScrollView = self.TabNodeScrollView
    local item = TabNodeScrollView:GetShownItemByItemIndex(index - 1)
    local mbEnv = CfUtils.GetLuaScr(item.gameObject, PrefabPathTabNode)
    if mbEnv == nil then return end
    mbEnv:RefreshSelectState(isSelect)
end

---RefreshHeadNodeScrollView
function UIBossDetailDialog:RefreshHeadNodeScrollView(oneWaveMonsterData)
    local scrollView = self.HeadNodeScrollView
    local count = table.count(oneWaveMonsterData)

    if not scrollView.IsListViewInit then
        scrollView:InitListView(count, Bind(self, self.OnGetHeadNodeItemByIndex))
    else
        GameUtils.ReloadData(scrollView, count)
    end
    scrollView.ScrollRect.vertical = count > 3
end

function UIBossDetailDialog:OnGetHeadNodeItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local position = index + 1
    -- 创建cell
    local cell = listView:NewListViewItem(PrefabNameHeadNode)

    if not KTool.IsNull(cell) then
        -- cell绑定的脚本
        local cellViewMB = GetLuaBehaviour(cell.gameObject, PrefabPathHeadNode)
        if not KTool.IsNull(cellViewMB) then
            ---@type UIBossDetailHeadNodeMB
            local mbEnv = cellViewMB.Env
            if not cell.IsInitHandlerCalled then
                cell.IsInitHandlerCalled = true
                mbEnv = cellViewMB.Env
                mbEnv:SetCallback(Bind(self, self.OnClickHeadNodeAction))
            end

            local oneRoundMonsterVos = self:GetOneRoundMonsterVos(self.tabIndex)
            local monsterTypeVo = oneRoundMonsterVos[position]
            mbEnv:RefreshUI(monsterTypeVo, position)
            mbEnv:RefreshShowState(position == self.monsterIndex)

        end
    end

    return cell
end

function UIBossDetailDialog:RefreshHeadNodeShowState(index, isSelect)
    local ScrollView = self.HeadNodeScrollView
    local item = ScrollView:GetShownItemByItemIndex(index - 1)
    if isNull(item) then return end
    local mbEnv = CfUtils.GetLuaScr(item.gameObject, PrefabPathHeadNode)
    if mbEnv == nil then return end
    mbEnv:RefreshShowState(isSelect)
end

---RefreshMonsterInfo
---@param monsterTypeVo MonsterTypeVo
function UIBossDetailDialog:RefreshMonsterInfo(monsterTypeVo)
    local skinId = monsterTypeVo.skinId
    --local cardSkinVo = cardConfMgr:GetCardSkinBySkinId(skinId)
    self:RefreshMonsterImage(monsterTypeVo)
    self:RefreshMonsterType(monsterTypeVo)
    self:RefreshMonsterName(monsterTypeVo)
    self:RefreshMonsterSkillInfo(monsterTypeVo)
end

---RefreshMonsterImage
---刷新怪物立绘
---@param monsterTypeVo MonsterTypeVo 皮肤id
function UIBossDetailDialog:RefreshMonsterImage(monsterTypeVo)
    local isRole = checkNumber(monsterTypeVo.role) > 0
    local pos    = isRole and Vector2.New(-254, -128) or Vector2.New(-225, -446)
    local choosePos = isRole and 1 or 3
    local fieldName = isRole and "cardDrawing" or "hdCardDrawing"
    self.BossDrawingNodeRT.anchoredPosition = pos
    self.BossDrawingNode:Execute(checkNumber(monsterTypeVo.skinId), choosePos, -1, fieldName)
end

---RefreshMonsterType
---@param monsterTypeVo MonsterTypeVo
function UIBossDetailDialog:RefreshMonsterType(monsterTypeVo)
    local weakness = monsterTypeVo.weakness
    local isSolution = weakness > 0
    KTool.SetActive(self.AttributeBackground.gameObject, not isSolution)
    KTool.SetActive(self.WeaknessButton.gameObject, isSolution)
    if not isSolution then
        --print("monsterTypeVo.attribute", monsterTypeVo.attribute)
        self.AttributeIcon.gameObject:EnsureComponent(ImageAlterableType):LoadSprite(UICommonUtils.GetMonsterAttributeIcon(monsterTypeVo.attribute))
    end

    KTool.SetActive(self.BossIcon.gameObject, monsterTypeVo.monsterClass == Constants.RoleClass.Boss)
    self.weakness = weakness
end

---RefreshMonsterName
---@param monsterTypeVo MonsterTypeVo
function UIBossDetailDialog:RefreshMonsterName(monsterTypeVo)
    local skinId = monsterTypeVo.skinId
    local cardSkinVo = cardConfMgr:GetCardSkinBySkinId(skinId)
    local name = cardSkinVo.name
    self.MonsterNameText.text = name
end

---RefreshMonsterTalent
---@param monsterTypeVo MonsterTypeVo
function UIBossDetailDialog:RefreshMonsterSkillInfo(monsterTypeVo)
    local monsterSkillData = self:InitMonsterSkillData(monsterTypeVo)

    local isOwnSkill = next(monsterSkillData) ~= nil
    if isOwnSkill then
        self:RefreshSkillScrollView(monsterSkillData)
    end
end

function UIBossDetailDialog:RefreshSkillScrollView(monsterSkillData)
    local scrollView = self.TalentSkillScrollView
    local count = table.count(monsterSkillData)
    if not scrollView.IsListViewInit then
        scrollView:InitListView(count, Bind(self, self.OnGetSkillItemByIndex))
    else
        GameUtils.ReloadData(scrollView, count)
    end
end

function UIBossDetailDialog:OnGetSkillItemByIndex(listView, index)
    if index < 0 then return nil end
    local position = index + 1
    local data = self.monsterSkillData[position]

    local isSp = data.isSp
    local PrefabName = isSp and PrefabNameSpSkillInfoNode or PrefabNameTalentSkillNode
    local PrefabPath = isSp and PrefabPathSpSkillInfoNode or PrefabPathTalentSkillNode

    -- 创建cell
    local cell = listView:NewListViewItem(PrefabName)

    if not KTool.IsNull(cell) then
        -- cell绑定的脚本
        local cellViewMB = GetLuaBehaviour(cell.gameObject, PrefabPath)
        if not KTool.IsNull(cellViewMB) then
            ---@type UIBossDetailTalentSkillNodeMB
            local mbEnv = cellViewMB.Env
            if not cell.IsInitHandlerCalled then
                cell.IsInitHandlerCalled = true
                mbEnv = cellViewMB.Env
            end

            mbEnv:RefreshUI(data)
        end
    end

    return cell
end

function UIBossDetailDialog:RefreshBG()
    local parameters = self.controller.Argument.parameters
    local levelId = parameters.levelId --- 关卡id
    local questVo = questConfMgr:GetQuestVoById(levelId)
    if isNotNull(questVo.bgPath)
    and not string.isEmpty(questVo.bgPath) then
        local effectCapture = self.controller.transform:Find("EffectCaptured")
        local imgBlack = self.controller.transform:Find("ImgBlack")
        KTool.SetActive(imgBlack, false)
        KTool.SetActive(effectCapture, true)
        local ec = effectCapture.gameObject:GetComponent(typeof(CS.UGUI.Effects.UIEffectCapturedImage))
        ec:Capture()
    end
end

