function UIBossDetailDialog:OnClickTabNodeAction(index)
    if self.tabIndex == index then return end

    self:RefreshTabNodeSelectState(self.tabIndex, false)
    self:RefreshTabNodeSelectState(index, true)
    self.tabIndex = index
    self.monsterIndex = 1

    self:RefreshUI()
end

function UIBossDetailDialog:OnClickHeadNodeAction(dataIndex)
    if self.monsterIndex == dataIndex then return end

    self:RefreshHeadNodeShowState(self.monsterIndex, false)
    self:RefreshHeadNodeShowState(dataIndex, true)
    self.monsterIndex = dataIndex

    local oneRoundMonsterVos = self:GetOneRoundMonsterVos(self.tabIndex)
    ---@type MonsterTypeVo
    local monsterTypeVo = oneRoundMonsterVos[dataIndex]
    self:RefreshMonsterInfo(monsterTypeVo)
end

function UIBossDetailDialog:OnClickWeaknessButtonAction(eventData)
    GameUtils.ShowCommonTipsBoardWeakness(self.WeaknessButton.gameObject, self.weakness)
end

function UIBossDetailDialog:OnClickCloseButtonAction()
    UIModule.BackDialog()
end

